// step-through procedure — Bowline (jahdb demo program)
var STEPS=["Form a small loop in the rope", "Pass the working end up through the loop", "Wrap it behind the standing part", "Tuck it back down through the small loop", "Dress and tighten"];
var _i=0;
function next(){if(_i<STEPS.length){console.log("Step "+(_i+1)+"/"+STEPS.length+": "+STEPS[_i]);_i++;}else{console.log("Procedure complete.");}}
function runAll(){while(_i<STEPS.length)next();}
function reset(){_i=0;}
// demo: run the whole procedure now
runAll();

